"use strict";

// The blocker an independent audit found against RWF-028's first
// implementation, kept as a permanent end-to-end control.
//
// Every wrapper below has a PARAMETER spelled `bail`, shadowing the
// module-scope throwing `bail`. At runtime each one invokes `safeFn` and
// returns, so `module.exports = safeOp` at the bottom really is written
// on every load -- confirmed by executing this file with real `node`.
//
// The first implementation resolved those bodies' `bail()` to the OUTER
// declaration, because the lexical ancestor walk stepped straight over
// the function boundary: `scopeDeclares` modelled catch clauses, loop
// bindings and statement lists, but not a function's own parameters.
// That withdrew this module's export authority and made its whole
// exported value ambiguous -- a false AFFECTED for a module that runs to
// completion.
//
// This module is scanned from `param-shadow-only.cjs`, which CALLS the
// exported value. The assertion is therefore about EXPORT ATTRIBUTION,
// not about Family C: with authority intact the export resolves to
// `safeOp` and the call reaches it; if the shadow were crossed again the
// whole-module export would be ambiguous and nothing would resolve.
//
// Note there is no Family C claim here and there cannot be: calling a
// PARAMETER is genuinely unresolvable, so the reachable subgraph is
// legitimately incomplete. That is why these controls live in their own
// module rather than in `valid.js`, whose job is the complete-subgraph
// negative proof.
function safeOp(input) {
  return "safe:" + input;
}

function safeFn() {
  return "safe";
}

function bail() {
  throw new Error("boom");
}

// 1/2 -- a plain parameter, and a later one.
function paramShadow(bail) {
  bail();
}
paramShadow(safeFn);

function secondParamShadow(x, bail) {
  void x;
  bail();
}
secondParamShadow(1, safeFn);

// 3 -- a default parameter. Inside the body `bail` is the PARAMETER,
// whatever the default initializer names.
function defaultParamShadow(bail = safeFn) {
  bail();
}
defaultParamShadow();

// 4/5 -- object destructuring, plain and renamed.
function destructuredParamShadow({ bail }) {
  bail();
}
destructuredParamShadow({ bail: safeFn });

function renamedParamShadow({ x: bail }) {
  bail();
}
renamedParamShadow({ x: safeFn });

// 6/7 -- array destructuring and rest.
function arrayParamShadow([bail]) {
  bail();
}
arrayParamShadow([safeFn]);

function restParamShadow(...bail) {
  bail[0]();
}
restParamShadow(safeFn);

// 8 -- an arrow's parameters bind exactly as a function's do.
const arrowParamShadow = (bail) => {
  bail();
};
arrowParamShadow(safeFn);

// 9 -- two hops, so the refusal has to happen at the INNER scope rather
// than at the call site the walk started from.
function innerParamShadow(bail) {
  bail();
}
function outerCallsInner() {
  innerParamShadow(safeFn);
}
outerCallsInner();

// 10 -- a named function EXPRESSION binds its own name inside its own
// body: `bail` here is this function, not the throwing declaration above.
const selfNamed = function bail() {
  return "self";
};
selfNamed();

module.exports = safeOp;
